import{_ as e,o as r,c as a,ae as o}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"Alipay Bill Import Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/03-alipay-bill-import-guide.md","filePath":"v1/en/guide/03-alipay-bill-import-guide.md"}'),l={name:"v1/en/guide/03-alipay-bill-import-guide.md"};function i(d,t,n,s,p,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="alipay-bill-import-guide" tabindex="-1">Alipay Bill Import Guide <a class="header-anchor" href="#alipay-bill-import-guide" aria-label="Permalink to &quot;Alipay Bill Import Guide&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>This guide shows how to export bills from Alipay and import them into Koala.</p><hr><h2 id="📱-part-1-export-bills-in-alipay" tabindex="-1">📱 Part 1: Export bills in Alipay <a class="header-anchor" href="#📱-part-1-export-bills-in-alipay" aria-label="Permalink to &quot;📱 Part 1: Export bills in Alipay&quot;">​</a></h2><h3 id="step-1-open-the-bill-page" tabindex="-1">Step 1: Open the bill page <a class="header-anchor" href="#step-1-open-the-bill-page" aria-label="Permalink to &quot;Step 1: Open the bill page&quot;">​</a></h3><ol><li>Open Alipay</li><li>Tap <strong>Me</strong></li><li>Tap <strong>Bills</strong></li></ol><blockquote><p>📝 Note: The entry may differ by version. If you can’t find it, try searching “账单”.</p></blockquote><h3 id="step-2-export" tabindex="-1">Step 2: Export <a class="header-anchor" href="#step-2-export" aria-label="Permalink to &quot;Step 2: Export&quot;">​</a></h3><ol><li>On the Bills page, tap <strong>...</strong> (top-right)</li><li>Choose <strong>账单导出</strong> or <strong>开具交易流水证明</strong></li><li>Select <strong>用户个人对帐</strong>, then submit/apply</li><li>Choose the transaction type and date range</li><li>Choose delivery method (<strong>Alipay</strong> or <strong>Email</strong>)</li></ol><blockquote><p>💡 Tips:</p><ul><li>Export up to 3 months at a time.</li><li>If delivered by email, download the CSV attachment.</li></ul></blockquote><hr><h2 id="📱-part-2-import-into-koala" tabindex="-1">📱 Part 2: Import into Koala <a class="header-anchor" href="#📱-part-2-import-into-koala" aria-label="Permalink to &quot;📱 Part 2: Import into Koala&quot;">​</a></h2><ol><li>Open Koala → <strong>Settings</strong> → <strong>Bill Import</strong></li><li>Set <strong>Import source</strong> to <strong>Alipay</strong></li><li>Choose the exported <strong>CSV</strong> file</li><li>Link the target ledger</li><li>Tap <strong>Parse</strong> → review → <strong>Import</strong></li></ol><hr><h2 id="📋-alipay-csv-columns-for-reference" tabindex="-1">📋 Alipay CSV columns (for reference) <a class="header-anchor" href="#📋-alipay-csv-columns-for-reference" aria-label="Permalink to &quot;📋 Alipay CSV columns (for reference)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column name (as exported)</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td>交易时间</td><td>Transaction time</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易分类</td><td>Category</td><td>餐饮美食</td></tr><tr><td>交易对方</td><td>Counterparty</td><td>张三 / 商户</td></tr><tr><td>对方账号</td><td>Counterparty account</td><td><a href="mailto:xxx@163.com" target="_blank" rel="noreferrer">xxx@163.com</a></td></tr><tr><td>商品说明</td><td>Item description</td><td>午餐</td></tr><tr><td>收/支</td><td>Income/Expense</td><td>收入 / 支出</td></tr><tr><td>金额</td><td>Amount</td><td>100.00</td></tr><tr><td>收/付款方式</td><td>Payment method/account</td><td>余额宝</td></tr><tr><td>交易状态</td><td>Status</td><td>交易成功</td></tr><tr><td>交易订单号</td><td>Transaction order no.</td><td>...</td></tr><tr><td>商家订单号</td><td>Merchant order no.</td><td>...</td></tr><tr><td>备注</td><td>Note</td><td>...</td></tr></tbody></table><hr><h2 id="⚠️-notes" tabindex="-1">⚠️ Notes <a class="header-anchor" href="#⚠️-notes" aria-label="Permalink to &quot;⚠️ Notes&quot;">​</a></h2><ul><li>Only <strong>CSV</strong> is supported for Alipay.</li><li>Don’t rename/delete headers or add columns manually.</li><li>If you export multiple files, import them one by one.</li></ul><hr><p><strong>Last updated</strong>: May 2026</p>',22)])])}const c=e(l,[["render",i]]);export{u as __pageData,c as default};
